char buf[] = "Payload";

struct iovec iov = { .iov_base = buf, .iov_len = sizeof(buf) };

#define VEC_LEN 2
struct mmsghdr msg_vec[VEC_LEN] = {
    { .msg_hdr = {
        .msg_name = NULL,
        .msg_namelen = 0,
        .msg_iov = &iov,
        .msg_iovlen = 1,
    }, .msg_len = 0 }, // Message 1 setup
    // Message 2 setup...
};

int sock_fd = 5;
unsigned int vlen = VEC_LEN;
int flags = 0;

// Returns number of messages successfully transmitted
int sent_count = sendmmsg(
    sock_fd,
    msg_vec,
    vlen,
    flags
);
